#ifndef REGATTARANK_H
#define REGATTARANK_H

#include <stddef.h>

#define RR_MAX_RACES 32

enum { RR_FINISHED = 0, RR_DNF = 1, RR_DSQ = 2 };
enum { RR_OK = 0, RR_E_TIME = 1, RR_E_RATING = 2, RR_E_STATUS = 3 };

typedef struct {
    int id;
    int status;
    long elapsed_s;
    int rating;
} rr_boat;

typedef struct {
    int place;
    long corrected_cs;
} rr_result;

